const assert = require('assert');
const { createCounter } = require('./counter.js');

const c1 = createCounter();
assert.strictEqual(c1.count.value, 0, 'default initial should be 0');
assert.strictEqual(c1.double.value, 0);

const c = createCounter(3);
assert.strictEqual(c.count.value, 3);
assert.strictEqual(c.double.value, 6, 'double should be count * 2');

c.increment();
assert.strictEqual(c.count.value, 4, 'increment should raise count by 1');
assert.strictEqual(c.double.value, 8, 'double should track count reactively');

c.increment();
c.increment();
assert.strictEqual(c.count.value, 6);
assert.strictEqual(c.double.value, 12);

